  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "In a rabbit pneumococcal meningitis model, oritavancin showed only 5% CSF/plasma penetration, indicating poor CNS access under the relevant condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Daptomycin achieved only 5% CSF penetration relative to serum in a rabbit Streptococcus pneumoniae meningitis model, and human CSF was undetectable despite therapeutic serum levels.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Dalbavancin-derived radioactivity in rabbit CSF was very low and measurable only at late time points, supporting limited CNS penetration for this related glycopeptide.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The most relevant and condition-matched evidence comes from oritavancin, a highly similar molecule, which shows only 1–5% CSF penetration in meningitis models. Related lipoglycopeptide/lipopeptide antibiotics also show poor CNS penetration, while positive BBB evidence comes from structurally dissimilar compounds without meningitis-condition data. Therefore, meaningful CNS access is not supported.",
  "evidence_gaps": [
    "No direct experimental data for the exact query molecule were provided; prediction relies on a highly similar analog.",
    "Positive BBB-penetration evidence comes from low-similarity molecules and non-meningitis conditions, limiting transferability."
  ],
